187	async function findChannelResourceEntityId(opts: {
188		organizationId: string;
189		connectorKey: string;
190		teamId: string | null | undefined;
191		channelId: string;
192		sql: DbClient;
193	}): Promise<number | null> {
194		if (opts.connectorKey === "slack" && !opts.teamId) return null;
195		const { namespace, key } = channelResourceIdentity(
196			opts.connectorKey,
197			opts.teamId,
198			opts.channelId,
199		);
200		const rows = await opts.sql<{ id: number }>`
201	    SELECT e.id
202	    FROM entity_identities ei
203	    JOIN entities e
204	      ON e.id = ei.entity_id
205	     AND e.organization_id = ei.organization_id
206	     AND e.deleted_at IS NULL
207	    WHERE ei.organization_id = ${opts.organizationId}
208	      AND ei.namespace = ${namespace}
209	      AND ei.identifier = ${key}
210	      AND ei.deleted_at IS NULL
211	    LIMIT 1
212	  `;
213		return rows[0] ? Number(rows[0].id) : null;
214	}
