394		const sql = opts.sql ?? getDb();
395		const typeId = await ensureAboutRelationshipType(opts.organizationId, sql);
396		const connectionId = String(opts.connectionId);
397		const { key } = channelResourceIdentity(
398			opts.connectorKey,
399			opts.teamId,
400			opts.channelId,
401		);
402	
403		const channelEntityId = await ensureChannelResourceEntity({
404			organizationId: opts.organizationId,
405			connectorKey: opts.connectorKey,
406			teamId: opts.teamId,
407			channelId: opts.channelId,
408			sql,
409		});
410		if (channelEntityId === null) {
411			throw new Error("Channel entity could not be resolved for this channel");
412		}
413	
414		const metadata: ChannelAboutMetadata = {
415			connection_id: connectionId,
416			channel_key: key,
417		};
418	
419		const desired = new Set(opts.aboutEntityIds.map(Number));
420	
421		const existing = await sql<{ id: number; to_entity_id: number }>`
422	    SELECT r.id, r.to_entity_id
423	    FROM entity_relationships r
424	    WHERE r.organization_id = ${opts.organizationId}
