  1	/**
  2	 * Entity merge — fold a duplicate `loser` entity into the `winner` it really is.
  3	 *
  4	 * The world-model keystone: when a bridge event (or a reviewer/watcher) reveals
  5	 * two entities are the same real thing, this fuses them WITHOUT rewriting the
  6	 * append-only `events` table. It runs off the ingest hot path — a user-configured
  7	 * watcher's agent, or an admin, calls it via `manage_entity(action='merge')`; the
  8	 * resolver only ever LOGS a "merge candidate", never fuses inline.
  9	 *
 10	 * Two disjoint event populations recall the winner afterward:
 11	 *   1. Identity/metadata-attributed events (connector-ingested): repaired HERE —
 12	 *      the loser's identities move to the winner, so the existing identity-graph
 13	 *      recall (entity_identities → events.metadata) finds them for free.
 14	 *   2. Raw `events.entity_ids`-stamped events (save_content memories, feed-pinned,
 15	 *      webhooks): can't be rewritten (append-only), so the loser stays as a
 16	 *      tombstone carrying `merged_into = winner`, and the recall redirect in
 17	 *      content-search/entity-link.ts gathers `{winner} ∪ {losers}` for the
 18	 *      `entity_ids @>` branch.
 19	 *
 20	 * Reversal uses the durable `entity_merge_operations` ledger to restore moved
 21	 * identities, canonical attributes, relationship endpoints, and flattened
 22	 * redirects. Undo fails closed when later edits no longer match that operation's
 23	 * after-state. Chains remain flattened (L→W→V stored as L→V, W→V) so reads stay
 24	 * one indexed hop; they must be undone from the outside in.
 25	 */
 26	
 27	import { isDeepStrictEqual } from "node:util";
 28	import { type DbClient, getDb, pgBigintArray } from "../db/client";
 29	import { mergeEntityState } from "../entity-resolution/merge-state";
 30	import {
 31		RESOLUTION_FINGERPRINT_VERSION,
 32		type ResolutionEvidence,
 33	} from "../entity-resolution/policy";
 34	import { assertResolutionFingerprintCurrent } from "../entity-resolution/staleness";
 35	import logger from "./logger";
 36	
 37	export interface MergeResolutionProvenance {
 38		decision: "auto_merge" | "human";
 39		sourceRunId?: number | null;
 40		watcherId?: number | null;
 41		windowId?: number | null;
 42		policyHash?: string | null;
 43		evidence?: ResolutionEvidence[];
 44	}
 45	
 46	export interface ApplyMergeParams {
 47	  orgId: string;
 48	  /** The duplicate that gets tombstoned + forwarded. */
 49	  loserId: number;
 50	  /** The surviving entity that absorbs the loser. */
 51	  winnerId: number;
 52	  /** Who triggered the merge (agent id / user id) — for the tombstone audit. */
 53	  mergedBy: string;
 54		resolution?: MergeResolutionProvenance;
 55	}
 56	
 57	export interface ApplyMergeResult {
 58	  movedIdentities: number;
 59	  repointedEdges: number;
 60	}
 61	
 62	export interface ApplyMergeGroupResult {
 63	  mergedEntityIds: number[];
 64	  movedIdentities: number;
 65	  repointedEdges: number;
 66	}
 67	
 68	export interface ApplyMergeGroupParams {
 69	  orgId: string;
 70	  loserIds: number[];
 71	  winnerId: number;
 72	  mergedBy: string;
 73		resolution?: MergeResolutionProvenance;
 74		expectedResolutionFingerprint?: string;
 75	}
 76	
 77	/**
 78	 * Apply a whole duplicate group under one outer transaction. Any stale or
 79	 * invalid member rolls back every preceding member merge.
 80	 */
 81	export async function applyMergeGroup(
 82	  params: ApplyMergeGroupParams,
 83	  db: DbClient = getDb(),
 84	): Promise<ApplyMergeGroupResult> {
 85		return db.begin((tx) => applyMergeGroupInTransaction(params, tx));
 86	}
 87	
 88	export async function applyMergeGroupInTransaction(
 89	  params: ApplyMergeGroupParams,
 90	  tx: DbClient,
 91	): Promise<ApplyMergeGroupResult> {
 92	  const loserIds = [...new Set(params.loserIds)].sort((a, b) => a - b);
 93		if (loserIds.length === 0)
 94			throw new Error("applyMergeGroup: no duplicate entities");
 95	  if (loserIds.includes(params.winnerId)) {
 96			throw new Error("applyMergeGroup: canonical entity is also a duplicate");
 97	  }
 98	
 99	  // Lock the whole group in one global order before applying any member. Pairwise
100	  // locking inside the loop is not sufficient: overlapping groups with different
101	  // winners can otherwise each hold one entity while waiting for the other.
102	  const entityIds = [...loserIds, params.winnerId].sort((a, b) => a - b);
103	  await tx`
104	    SELECT id
105	    FROM entities
106	    WHERE organization_id = ${params.orgId}
107	      AND id = ANY(${pgBigintArray(entityIds)}::bigint[])
108	    ORDER BY id
109	    FOR UPDATE
110	  `;
111	
112		if (params.expectedResolutionFingerprint) {
113			await assertResolutionFingerprintCurrent(tx, {
114				organizationId: params.orgId,
115				winnerId: params.winnerId,
116				loserIds,
117				expectedFingerprint: params.expectedResolutionFingerprint,
118				// Computed by this process moments ago, so it is current by
119				// construction — never a stored digest from an older format.
120				expectedVersion: RESOLUTION_FINGERPRINT_VERSION,
121			});
122		}
123	
124	  let movedIdentities = 0;
125	  let repointedEdges = 0;
126	  for (const loserId of loserIds) {
127	    const result = await applyMergeInTransaction(
128	      {
129	        orgId: params.orgId,
130	        loserId,
131	        winnerId: params.winnerId,
132	        mergedBy: params.mergedBy,
133					resolution: params.resolution,
134	      },
135	      tx,
136	    );
137	    movedIdentities += result.movedIdentities;
138	    repointedEdges += result.repointedEdges;
139	  }
140	  return { mergedEntityIds: loserIds, movedIdentities, repointedEdges };
141	}
142	
143	/**
144	 * Fuse `loser` into `winner` in one transaction. Idempotent-safe on re-run: a
145	 * loser already merged into this winner returns a zero result rather than
146	 * throwing. Throws on a cross-entity-type or already-merged-elsewhere conflict so
147	 * the caller (tool) surfaces it rather than silently corrupting the graph.
148	 */
149	export async function applyMerge(
150	  params: ApplyMergeParams,
151	  db: DbClient = getDb(),
152	): Promise<ApplyMergeResult> {
153		return db.begin((tx) => applyMergeInTransaction(params, tx));
154	}
155	
156	async function applyMergeInTransaction(
157	  params: ApplyMergeParams,
158	  tx: DbClient,
159	): Promise<ApplyMergeResult> {
160	  const { orgId, loserId, winnerId, mergedBy } = params;
161	  if (loserId === winnerId) {
162			throw new Error("applyMerge: loser and winner are the same entity");
163	  }
164	
165	  // Lock both rows in a stable order (lowest id first) to avoid deadlocks when
166	  // two merges touch the overlapping pair concurrently.
167	  const [a, b] = loserId < winnerId ? [loserId, winnerId] : [winnerId, loserId];
168	  const locked = await tx<{
169	    id: number;
170	    entity_type_id: number;
171	    merged_into: number | null;
172	    deleted_at: string | null;
173			name: string;
174			metadata: Record<string, unknown>;
175			field_controls: Record<string, unknown>;
176	  }>`
177	    SELECT id, entity_type_id, merged_into, deleted_at, name, metadata, field_controls
178	    FROM entities
179	    WHERE organization_id = ${orgId} AND id IN (${a}, ${b})
180	    ORDER BY id
181	    FOR UPDATE
182	  `;
183	
184	  const loser = locked.find((row) => Number(row.id) === loserId);
185	  const winner = locked.find((row) => Number(row.id) === winnerId);
186	  if (!loser || !winner) {
187			throw new Error(
188				`applyMerge: entity not found in org (loser=${loserId} winner=${winnerId})`,
189			);
190	  }
191	  if (Number(loser.merged_into) === winnerId) {
192	    return { movedIdentities: 0, repointedEdges: 0 };
193	  }
194	  if (loser.merged_into !== null) {
195			throw new Error(
196				`applyMerge: loser ${loserId} already merged into ${loser.merged_into}`,
197			);
198	  }
199	  if (loser.deleted_at !== null) {
200	    throw new Error(`applyMerge: loser ${loserId} is deleted`);
201	  }
202	  if (winner.merged_into !== null) {
203			throw new Error(
204				`applyMerge: winner ${winnerId} is itself merged into ${winner.merged_into}`,
205			);
206	  }
207	  if (winner.deleted_at !== null) {
208	    throw new Error(`applyMerge: winner ${winnerId} is deleted`);
209	  }
210	  if (Number(loser.entity_type_id) !== Number(winner.entity_type_id)) {
211			throw new Error(
212				"applyMerge: cannot merge entities of different entity types",
213			);
214	  }
215	
216		const identitiesBefore = await tx<{
217			id: number;
218			merged_from_entity_id: number | null;
219		}>`
220	    SELECT id, merged_from_entity_id
221	    FROM entity_identities
222	    WHERE organization_id = ${orgId}
223	      AND entity_id = ${loserId}
224	      AND deleted_at IS NULL
225	    ORDER BY id
226	    FOR UPDATE
227	  `;
228	
229		const relationshipsBefore = await tx<{
230			id: number;
231			from_entity_id: number;
232			to_entity_id: number;
233			deleted_at: Date | string | null;
234		}>`
235	    SELECT id, from_entity_id, to_entity_id, deleted_at
236	    FROM entity_relationships
237	    WHERE organization_id = ${orgId}
238	      AND deleted_at IS NULL
239	      AND (from_entity_id = ${loserId} OR to_entity_id = ${loserId})
240	    ORDER BY id
241	    FOR UPDATE
242	  `;
243	
244	  // 1. Move the loser's LIVE identities to the winner. A live loser↔live winner
245	  //    collision on the SAME (org, namespace, identifier) is impossible — the
246	  //    global unique index `idx_entity_identities_live_unique` forbids two live
247	  //    rows for one value org-wide — so the move can never hit the index. Stamp
248	  //    origin with COALESCE so an identity that already carries a marker (moved
249	  //    here by an EARLIER merge, e.g. L→W then W→V) keeps its INNERMOST origin —
250		//    the outer operation ledger can then put it back on W without losing L's
251		//    provenance.
252	  const moved = (await tx<{ id: number }>`
253	    UPDATE entity_identities
254	    SET entity_id = ${winnerId},
255	        merged_from_entity_id = COALESCE(merged_from_entity_id, ${loserId}),
256	        updated_at = current_timestamp
257	    WHERE organization_id = ${orgId}
258	      AND entity_id = ${loserId}
259	      AND deleted_at IS NULL
260	    RETURNING id
261	  `) as Array<{ id: number }>;
262	
263		// 2. Merge complementary attributes. Scalar conflicts keep the canonical
264		//    winner; arrays are unioned; missing fields and ownership markers move.
265		//    The exact before/after pair is persisted below so Undo is lossless.
266		const mergedState = mergeEntityState(
267			{
268				name: winner.name,
269				metadata: winner.metadata ?? {},
270				fieldControls: winner.field_controls ?? {},
271			},
272			{
273				name: loser.name,
274				metadata: loser.metadata ?? {},
275				fieldControls: loser.field_controls ?? {},
276			},
277		);
278	  await tx`
279	    UPDATE entities
280	    SET metadata = ${tx.json(mergedState.metadata)},
281	        field_controls = ${tx.json(mergedState.fieldControls)},
282	        updated_at = current_timestamp
283	    WHERE id = ${winnerId} AND organization_id = ${orgId}
284	  `;
285	
286	  // 3. Tombstone loser edges that would become self-loops or collide with an
287	  //    existing winner edge. This must happen before repointing: the live-edge
288	  //    unique index rejects the collision during UPDATE, before a later cleanup
289	  //    statement could run.
290	  await tx`
291	    UPDATE entity_relationships r
292	    SET deleted_at = current_timestamp, updated_at = current_timestamp
293	    WHERE r.organization_id = ${orgId}
294	      AND r.deleted_at IS NULL
295	      AND (r.from_entity_id = ${loserId} OR r.to_entity_id = ${loserId})
296	      AND (
297	        (CASE WHEN r.from_entity_id = ${loserId} THEN ${winnerId} ELSE r.from_entity_id END) =
298	        (CASE WHEN r.to_entity_id = ${loserId} THEN ${winnerId} ELSE r.to_entity_id END)
299	        OR EXISTS (
300	          SELECT 1
301	          FROM entity_relationships o
302	          WHERE o.organization_id = ${orgId}
303	            AND o.deleted_at IS NULL
304	            AND o.id <> r.id
305	            AND o.relationship_type_id = r.relationship_type_id
306	            AND o.from_entity_id = CASE
307	              WHEN r.from_entity_id = ${loserId} THEN ${winnerId}
308	              ELSE r.from_entity_id
309	            END
310	            AND o.to_entity_id = CASE
311	              WHEN r.to_entity_id = ${loserId} THEN ${winnerId}
312	              ELSE r.to_entity_id
313	            END
314	        )
315	      )
316	  `;
317	
318	  // Repoint only the non-colliding live edges that remain.
319	  const repointed = (await tx<{ id: number }>`
320	    UPDATE entity_relationships
321	    SET from_entity_id = CASE WHEN from_entity_id = ${loserId} THEN ${winnerId} ELSE from_entity_id END,
322	        to_entity_id   = CASE WHEN to_entity_id   = ${loserId} THEN ${winnerId} ELSE to_entity_id   END,
323	        updated_at = current_timestamp
324	    WHERE organization_id = ${orgId}
325	      AND deleted_at IS NULL
326	      AND (from_entity_id = ${loserId} OR to_entity_id = ${loserId})
327	    RETURNING id
328	  `) as Array<{ id: number }>;
329	
330	  // 4. Flatten: anything that already pointed at the loser now points at the
331	  //    winner, so every redirect stays exactly one hop (no chain walk at read).
332	  //    The read redirect (`entity_ids && ARRAY(… merged_into = X …)`) is a
333	  //    one-time indexed lookup even when X is an outer column, which a recursive
334	  //    chain walk would NOT be on list/count/order call sites. The identities'
335	  //    COALESCE'd `merged_from` markers (step 1) preserve reversibility that
336	  //    the flattened `merged_into` pointer alone would lose.
337		const redirected = await tx<{ id: number }>`
338	    UPDATE entities
339	    SET merged_into = ${winnerId}, updated_at = current_timestamp
340	    WHERE organization_id = ${orgId} AND merged_into = ${loserId}
341	    RETURNING id
342	  `;
343	
344	  // 5. Tombstone the loser and point it at the winner.
345	  await tx`
346	    UPDATE entities
347	    SET merged_into = ${winnerId}, deleted_at = current_timestamp, updated_at = current_timestamp
348	    WHERE organization_id = ${orgId} AND id = ${loserId}
349	  `;
350	
351		const relationshipIds = relationshipsBefore.map((row) => Number(row.id));
352		const relationshipsAfter =
353			relationshipIds.length > 0
354				? await tx<{
355						id: number;
356						from_entity_id: number;
357						to_entity_id: number;
358						deleted_at: Date | string | null;
359					}>`
360	        SELECT id, from_entity_id, to_entity_id, deleted_at
361	        FROM entity_relationships
362	        WHERE organization_id = ${orgId}
363	          AND id = ANY(${pgBigintArray(relationshipIds)}::bigint[])
364	        ORDER BY id
365	      `
366				: [];
367		const afterById = new Map(
368			relationshipsAfter.map((row) => [Number(row.id), row]),
369		);
370		const timestamp = (value: Date | string | null): string | null =>
371			value === null ? null : new Date(value).toISOString();
372		const ledger = {
373			winner: {
374				metadataBefore: winner.metadata ?? {},
375				metadataAfter: mergedState.metadata,
376				fieldControlsBefore: winner.field_controls ?? {},
377				fieldControlsAfter: mergedState.fieldControls,
378			},
379			identities: identitiesBefore.map((identity) => ({
380				id: Number(identity.id),
381				mergedFromEntityId:
382					identity.merged_from_entity_id == null
383						? null
384						: Number(identity.merged_from_entity_id),
385			})),
386			redirectedEntityIds: redirected.map((entity) => Number(entity.id)),
387			relationships: relationshipsBefore.map((before) => {
388				const after = afterById.get(Number(before.id));
389				if (!after)
390					throw new Error(`applyMerge: relationship ${before.id} disappeared`);
391				return {
392					id: Number(before.id),
393					before: {
394						fromEntityId: Number(before.from_entity_id),
395						toEntityId: Number(before.to_entity_id),
396						deletedAt: timestamp(before.deleted_at),
397					},
398					after: {
399						fromEntityId: Number(after.from_entity_id),
400						toEntityId: Number(after.to_entity_id),
401						deletedAt: timestamp(after.deleted_at),
402					},
403				};
404			}),
405		};
406		const resolution = params.resolution ?? { decision: "human" as const };
407		await tx`
408	    INSERT INTO entity_merge_operations
409	      (organization_id, winner_entity_id, loser_entity_id, source_run_id,
410	       watcher_id, window_id, decision, policy_hash, evidence, ledger, merged_by)
411	    VALUES
412	      (${orgId}, ${winnerId}, ${loserId}, ${resolution.sourceRunId ?? null},
413	       ${resolution.watcherId ?? null}, ${resolution.windowId ?? null},
414	       ${resolution.decision}, ${resolution.policyHash ?? null},
415	       ${tx.json(resolution.evidence ?? [])}, ${tx.json(ledger)}, ${mergedBy})
416	  `;
417	
418	  logger.info(
419	    {
420	      orgId,
421	      loserId,
422	      winnerId,
423	      mergedBy,
424	      movedIdentities: moved.length,
425	      repointedEdges: repointed.length,
426	    },
427			"entity merge applied",
428	  );
429	
430	  return {
431	    movedIdentities: moved.length,
432	    repointedEdges: repointed.length,
433	  };
434	}
435	
436	export interface ApplyUnmergeParams {
437	  orgId: string;
438	  /** The tombstoned loser to split back out. */
439	  loserId: number;
440	  /** Who triggered the un-merge — for the audit log. */
441	  unmergedBy: string;
442	}
443	
444	export interface ApplyUnmergeResult {
445	  winnerId: number;
446	  /** Identities moved back from the winner to the loser. */
447	  restoredIdentities: number;
448	}
449	
450	/**
451	 * Reverse a merge: split `loser` back out of the winner. The durable operation
452	 * ledger restores moved identities, canonical metadata, field ownership,
453	 * relationship endpoints, and redirects flattened by this operation.
454	 *
455	 * Chains: `applyMerge` FLATTENS, so every tombstoned loser points at the TERMINAL
456	 * winner. In `L→W→V`, undo W→V first; that restores L→W and all identities W
457	 * held before the outer merge. L→W can then be undone exactly. Attempting to
458	 * undo L directly while it points at V fails closed.
459	 */
460	export async function applyUnmerge(

   620		metadata: Record<string, unknown>,
   621		schema: Record<string, unknown> | null | undefined,
   622	): Record<string, unknown> {
   623	  const { emailField } = resolveMemberSchemaFieldsFromSchema(schema);
   624	  if (!(emailField in metadata)) return metadata;
   625	  const { [emailField]: _removed, ...rest } = metadata;
   626	  return rest;
   627	}
   628	
   629	/**
   630	 * Fold a duplicate entity (`entity_id`, the loser) into the one it really is
   631	 * (`winner_entity_id`). Humans must be admin/owner. Agents and watchers may
   632	 * auto-merge only when the entity type policy proves the match; every other
   633	 * candidate queues human review. The heavy lifting (merge attributes, move
   634	 * identities and edges, tombstone + forward each loser, flatten chains) is in
   635	 * `applyMergeGroup`; this handler is the org-scoped gate + validation.
   636	 */
   637	async function handleMerge(
   638		args: ManageEntityArgs,
   639		ctx: ToolContext,
   640	): Promise<ManageEntityResult> {
   641		const actor = await actingPrincipalFor(args, ctx);
   642		if (actor.kind === "user" && !isAdminOrOwnerRole(ctx.memberRole)) {
   643			throw new ToolUserError("Only an admin or owner may merge entities", 403);
   644		}
   645		const loserIds = [
   646			...new Set(
   647				args.duplicate_entity_ids ?? (args.entity_id ? [args.entity_id] : []),
   648			),
   649		].sort((a, b) => a - b);
   650		const winnerId = args.winner_entity_id;
   651		if (loserIds.length === 0)
   652			throw new ToolUserError(
   653				"entity_id or duplicate_entity_ids is required for merge",
   654				400,
   655			);
   656		if (!winnerId)
   657			throw new ToolUserError(
   658				"winner_entity_id (the survivor) is required for merge",
   659				400,
   660			);
   661		if (loserIds.includes(winnerId))
   662			throw new ToolUserError("winner_entity_id cannot also be a duplicate", 400);
   663		if (loserIds.length > 25)
   664			throw new ToolUserError("A merge can include at most 25 duplicates", 400);
   665	
   666		const sql = getDb();
   667		// Every duplicate and the winner must be live and in the caller's org — never
   668		// merge across a tenant boundary or into a deleted/foreign entity.
   669		const rows = (await sql`
   670	    SELECT e.id, e.entity_type_id, e.metadata, et.metadata_schema,
   671	           et.slug AS entity_type_slug
   672	    FROM entities e
   673	    JOIN entity_types et ON et.id = e.entity_type_id
   674		WHERE e.organization_id = ${ctx.organizationId}
   675		      AND e.id = ANY(${pgBigintArray([...loserIds, winnerId])}::bigint[])
   676		      AND e.deleted_at IS NULL
   677		`) as Array<{
   678			id: number;
   679			entity_type_id: number;
   680			metadata: Record<string, unknown>;
   681			metadata_schema: Record<string, unknown> | null;
