 132	/**
 133	 * Schema-validation failures are user input errors, not duplicates: they carry
 134	 * a `[invalid_schema]` marker + httpStatus 422 so REST callers (`lobu apply`)
 135	 * can tell them apart from create-on-duplicate (`[entity_type_exists]`, 409)
 136	 * instead of guessing from the status code alone (issue #1177 — a 422 here
 137	 * used to be mistaken for "already exists", triggering a doomed update retry
 138	 * that buried the real message under "Entity type not found").
 139	 */
 140	function invalidSchema(message: string): ToolUserError {
 141	  return new ToolUserError(`[invalid_schema] ${message}`, 422);
 142	}
