 144	/**
 145	 * Authoritative server-side validation of a declared metrics_config. Catches
 146	 * the referential/shape errors the CLI also checks (a measure naming a missing
 147	 * eventSet/segment, a non-`count` measure without `expr`), so a non-CLI writer
 148	 * (SDK / API) cannot persist a broken metric contract. No-op for null/omitted.
 149	 */
 150	function assertValidMetricsConfig(metricsConfig: unknown): void {
 151	  if (metricsConfig == null) return;
 152	  const errors = validateEntityMetrics(metricsConfig);
 153	  if (errors.length > 0) {
 154	    throw invalidSchema(`invalid metrics_config: ${errors.join('; ')}`);
 155	  }
 156	}
