 158	function validateEntityMetadataSchemaDisplayConfig(
 159	  metadataSchema: Record<string, unknown> | undefined
 160	): void {
 161	  if (!metadataSchema || typeof metadataSchema !== 'object' || Array.isArray(metadataSchema)) {
 162	    return;
 163	  }
 164	
 165	  const properties = metadataSchema.properties;
 166	  if (!properties || typeof properties !== 'object' || Array.isArray(properties)) {
 167	    return;
 168	  }
 169	
 170	  for (const [field, prop] of Object.entries(properties)) {
 171	    if (!prop || typeof prop !== 'object' || Array.isArray(prop)) continue;
 172	
 173	    const tableColumn = (prop as Record<string, unknown>)['x-table-column'];
 174	    if (tableColumn !== undefined && typeof tableColumn !== 'boolean') {
 175	      throw invalidSchema(`metadata_schema.properties.${field}.x-table-column must be a boolean`);
 176	    }
 177	
 178	    const tableLabel = (prop as Record<string, unknown>)['x-table-label'];
 179	    if (tableLabel !== undefined && typeof tableLabel !== 'string') {
 180	      throw invalidSchema(`metadata_schema.properties.${field}.x-table-label must be a string`);
 181	    }
 182	  }
 183	}
