 185	/**
 186	 * Reject an empty/whitespace `backing.sql`. TypeBox `minLength: 1` accepts a
 187	 * whitespace-only string, so boundary validation alone would let a caller
 188	 * persist a "derived" type whose view is blank — unqueryable and with no
 189	 * inferable measures. `backing: null` (revert to stored) is fine. The
 190	 * `[invalid_schema]`/422 error shape here is a contract `lobu apply` parses.
 191	 */
 192	function assertValidBacking(backing: ManageEntitySchemaArgs['backing']): void {
 193	  if (backing && typeof backing.sql === 'string' && backing.sql.trim() === '') {
 194	    throw invalidSchema('backing.sql cannot be empty');
 195	  }
 196	  // Symmetric guard: an empty `connection` would persist backing_source='' — a
 197	  // slug that resolves to no connection, failing only at read time.
 198	  if (backing && typeof backing.connection === 'string' && backing.connection.trim() === '') {
 199	    throw invalidSchema('backing.connection cannot be empty');
 200	  }
 201	}
