1000	  const sql = getDb();
1001	
1002	  // Org-scoped duplicate check — the unique index is (organization_id, slug),
1003	  // so a same-slug PUBLIC type from another org must NOT block this org from
1004	  // creating its own (matches entity-type create).
1005	  const existing = await sql`
1006	    SELECT id FROM entity_relationship_types
1007	    WHERE slug = ${args.slug} AND deleted_at IS NULL
1008	      AND organization_id = ${ctx.organizationId}
