1027	  let inserted: unknown[];
1028	  try {
1029	    inserted = await sql`
1030	    INSERT INTO entity_relationship_types (
1031	      slug, name, description, organization_id, created_by,
1032	      metadata_schema, metadata, is_symmetric, inverse_type_id, status,
1033	      created_at, updated_at
1034	    ) VALUES (
