140	export function githubReposToResources(repos: GithubRepoInput[]): AccessResource[] {
141	  const resources: AccessResource[] = [];
142	  for (const repo of repos) {
143	    const key = normalizeGithubRepoFullName(repo.fullName);
144	    if (!key) continue;
145	    const members: AccessMember[] = [];
146	    for (const c of repo.collaborators) {
147	      const login = normalizeGithubLogin(c.login);
148	      const idValue = c.id != null ? normalizeNumericId(String(c.id)) : null;
149	      const identities: { namespace: string; value: string }[] = [];
150	      if (idValue) identities.push({ namespace: GITHUB_IDENTITY.USER_ID, value: idValue });
151	      if (login) identities.push({ namespace: GITHUB_IDENTITY.LOGIN, value: login });
152	      if (identities.length === 0) continue;
153	      members.push({ key: idValue ?? (login as string), name: c.login, identities });
154	    }
155	    resources.push({ key, name: repo.fullName, members });
156	  }
157	  return resources;
