203	/**
204	 * Filter bound channels down to what the requester may actually read. By
205	 * default, channels on never-graphed connections preserve legacy access;
206	 * callers granting access to non-owners can disable that fallback. Channels on
207	 * enforced connections survive only when the requester is provably `member_of`
208	 * them. An enforced channel with no team id, or an unresolvable requester, is
209	 * dropped.
210	 *
211	 * Returns the surviving rows (same objects, filtered) — the caller keeps its
212	 * existing per-channel query shape, just over a possibly-smaller set.
213	 */
214	export async function filterChannelsForRequester<T extends GatedChannelRow>(
215	  sql: DbClient,
216	  params: {
217	    organizationId: string;
218	    userId: string | null;
219	    rows: T[];
220	    allowNotGraphed?: boolean;
221	  },
222	): Promise<T[]> {
223	  const { organizationId, userId, rows, allowNotGraphed = true } = params;
224	  if (rows.length === 0) return rows;
225	
226	  const states = await getConnectionEnforcement(
227	    sql,
228	    organizationId,
229	    rows.map((r) => r.id),
230	  );
231	  // No connection onboarded into authz → no per-user gating to apply; preserve
232	  // legacy behavior without paying for member resolution.
233	  if (states.size === 0) return allowNotGraphed ? rows : [];
234	
235	  // Only resolve the requester's membership when at least one connection is
236	  // actively enforcing (full+fresh). Onboarded-but-stale connections fail closed
237	  // regardless of who is asking, so they need no membership lookup.
238	  const anyEnforcing = [...states.values()].some((s) => s.status === "enforced");
239	  const seenTenant = new Set<string>();
240	  const enforcingTenants: EnforcingTenant[] = [];
241	  for (const r of rows) {
242	    if (states.get(r.id)?.status !== "enforced" || !r.team_id) continue;
243	    const dedupe = `${r.platform}\u0000${r.team_id}`;
244	    if (seenTenant.has(dedupe)) continue;
245	    seenTenant.add(dedupe);
246	    enforcingTenants.push({ platform: r.platform, teamId: r.team_id });
247	  }
248	  const memberEntityId = anyEnforcing
249	    ? await resolveRequesterMember(sql, organizationId, userId, enforcingTenants)
250	    : null;
251	  const visibleKeys =
252	    memberEntityId === null
253	      ? new Set<string>()
254	      : await getVisibleChannelKeysForMember(sql, organizationId, memberEntityId);
255	
256	  return rows.filter((r) => {
257	    const state = states.get(r.id);
258	    if (!state) return allowNotGraphed; // never graphed → optional legacy fence
259	    if (state.status !== "enforced") return false; // stale/unsupported → fail closed
260	    const key = rowToChannelKey(r);
261	    if (key === null) return false; // no team id → can't form the key → fail closed
262	    return visibleKeys.has(key);
263	  });
264	}

