 34			typeof methodAccess === "string" ? [methodAccess] : methodAccess;
 35		const required = accesses.reduce<ToolAccessLevel>((highest, access) => {
 36			const candidate = requiredToolAccess(access);
 37			return TOOL_ACCESS_RANK[candidate] > TOOL_ACCESS_RANK[highest]
 38				? candidate
 39				: highest;
 40		}, "read");
 41		return required === "admin"
 42			? "administer"
 43			: required === "write"
 44				? "operate"
 45				: "read";
