 68	/**
 69	 * Resolve the effective tier for a method/lifecycle and, when unavailable,
 70	 * give the caller a role-aware next step. Scope elevation helps an owner/admin;
 71	 * it can never turn a regular member into a workspace administrator.
 72	 */
 73	export function resolveSdkAccessGuidance(
 74		methodAccess: MethodAccess | readonly MethodAccess[],
 75		memberRole: string | null | undefined,
 76		scopes: readonly string[] | null | undefined,
 77	): SdkAccessGuidance {
 78		const requiredTier = effectiveSdkRequiredTier(methodAccess);
 79		const requiredAccess: ToolAccessLevel =
 80			requiredTier === "administer"
 81				? "admin"
 82				: requiredTier === "operate"
 83					? "write"
 84					: "read";
 85		const currentAccess = resolveMaxAccessLevel(memberRole, scopes);
 86		const available =
 87			TOOL_ACCESS_RANK[currentAccess] >= TOOL_ACCESS_RANK[requiredAccess];
 88		if (available) return { requiredTier, available };
 89	
 90		if (requiredTier === "administer") {
 91			const isWorkspaceAdmin = memberRole === "owner" || memberRole === "admin";
 92			const progressivelyAuthorizable =
 93				isWorkspaceAdmin &&
 94				TOOL_ACCESS_RANK[resolveSdkMaxAccessLevel(memberRole, scopes)] >=
 95					TOOL_ACCESS_RANK.admin;
 96			return {
 97				requiredTier,
 98				available,
 99				...(progressivelyAuthorizable ? { progressivelyAuthorizable: true } : {}),
100				instruction: progressivelyAuthorizable
101					? "This lifecycle requires administer access (workspace owner/admin + mcp:admin). The admin methods are progressively authorizable through run_sdk: invoking one will return the standard mcp:admin OAuth challenge; after approval, retry the call and repeat search_sdk."
102					: isWorkspaceAdmin
103						? "This lifecycle requires administer access (workspace owner/admin + mcp:admin). Reconnect or reauthorize this MCP connection with write access first, then repeat search_sdk."
104						: "This lifecycle requires administer access (workspace owner/admin + mcp:admin). Ask a workspace owner/admin to continue; changing MCP scopes cannot elevate a regular member to administer access.",
105			};
106		}
107	
108		if (requiredTier === "operate") {
109			return {
110				requiredTier,
111				available,
112				instruction: memberRole
113					? "This action requires operate access (mcp:write). Reconnect or reauthorize this MCP connection with mcp:write, then repeat search_sdk."
114					: "This action requires operate access (workspace member + mcp:write). Ask a workspace member to continue.",
115			};
116		}
117	
118		// requiredTier "read": resolveMaxAccessLevel floors at "read", so the
119		// `available` early return above always fires before reaching here.
120		return { requiredTier, available };
121	}
