 11	 * result is retained for server-side diagnostics and recovery code, while the
 12	 * Error contract makes run_sdk/query_sdk fail instead of reporting success.
 13	 */
 14	export class ClientSdkActionError extends ToolUserError {
 15		readonly action: string;
 16		readonly result: Readonly<Record<string, unknown>>;
 17	
 18		constructor(
 19			action: string,
 20			message: string,
 21			result: Record<string, unknown>,
 22		) {
 23			super(message, 400);
 24			this.name = "ClientSdkActionError";
