 30	/**
 31	 * Resolve a single-id argument for a method documented as
 32	 * `path(field: type)` — the canonical positional form — while also accepting
 33	 * the intuitive object form `path({ field: value })` (#2046 contract-alias
 34	 * window). The object form is strict: exactly the canonical field, no extra
 35	 * keys, so options are never silently dropped. Anything else fails with
 36	 * guidance naming BOTH accepted call shapes and a neutral placeholder (never
 37	 * a real-looking id an agent might copy verbatim).
 38	 */
 39	export function idArg(
 40		method: string,
 41		field: string,
 42		value: unknown,
 43		kind: "number" | "string",
 44	): number | string {
 45		const matches = (v: unknown): boolean =>
 46			kind === "number"
 47				? typeof v === "number" && Number.isFinite(v)
 48				: typeof v === "string";
 49		if (matches(value)) return value as number | string;
 50		if (value && typeof value === "object" && !Array.isArray(value)) {
 51			const record = value as Record<string, unknown>;
 52			const keys = Object.keys(record);
 53			if (keys.length === 1 && keys[0] === field && matches(record[field])) {
 54				return record[field] as number | string;
 55			}
 56		}
 57		const placeholder = kind === "number" ? `<${field}>` : `'<${field}>'`;
 58		throw new ToolUserError(
 59			`${method} expects the ${field}. Call client.${method}(${placeholder}) or client.${method}({ ${field}: ${placeholder} }).`,
 60		);
 61	}
 62	
 63	function failureMessage(
 64		actionName: string,
 65		value: unknown,
 66	): { message: string; result: Record<string, unknown> } | null {
 67		if (!value || typeof value !== "object" || Array.isArray(value)) return null;
 68		const result = value as Record<string, unknown>;
 69		const hasError = result.error !== undefined && result.error !== null;
 70		const summary =
 71			result.summary &&
 72			typeof result.summary === "object" &&
 73			!Array.isArray(result.summary)
 74				? (result.summary as Record<string, unknown>)
 75				: null;
 76		const allAggregateItemsFailed =
 77			typeof summary?.failed === "number" &&
 78			summary.failed > 0 &&
 79			summary.successful === 0;
 80		// Some mutation policies return `success:false` while durably queueing an
 81		// approval. That is a non-terminal accepted outcome, not a business failure;
 82		// callers need its approval URL/run id to continue the workflow.
 83		const acceptedForApproval = result.approval_queued === true;
 84		const reportsFailure =
 85			!acceptedForApproval &&
 86			(result.success === false ||
 87				result.ok === false ||
 88				result.status === "failed" ||
 89				result.status === "error" ||
 90				result.status === "timeout" ||
 91				allAggregateItemsFailed);
 92		if (!hasError && !reportsFailure) return null;
 93		const failedItem = Array.isArray(result.results)
 94			? result.results.find(
 95					(item): item is Record<string, unknown> =>
 96						item !== null &&
 97						typeof item === "object" &&
 98						!Array.isArray(item) &&
 99						(item as Record<string, unknown>).success === false,
100				)
101			: undefined;
102	
103		const candidates = [
104			result.error,
105			result.error_message,
106			result.message,
107			result.reason,
108			failedItem?.error,
109			failedItem?.error_message,
110			failedItem?.message,
111			failedItem?.reason,
112		];
113		const message = candidates.find(
114			(candidate): candidate is string =>
115				typeof candidate === "string" && candidate.trim().length > 0,
116		);
117		return {
118			message: message?.trim() ?? `ClientSDK action '${actionName}' failed`,
119			result,
120		};
121	}
