128	/**
129	 * Rewrite a leaked internal tool name in a validation error to the public SDK
130	 * method the caller actually invoked. An arg-validation failure raised deep in
131	 * an admin handler reads `Invalid arguments for manage_feeds: …`, but a fresh
132	 * agent only ever called `client.feeds.get` — `manage_feeds` is internal
133	 * plumbing it cannot search or recover against. When the namespace is known,
134	 * swap `manage_<x>` for `client.<namespace>.<method>` and keep the field-level
135	 * detail (`/feed_id: Expected required property`) intact.
136	 */
137	function rewriteInternalToolName(
138		err: unknown,
139		sdkNamespace: string | undefined,
140		publicMethod: string,
141	): unknown {
142		if (!sdkNamespace || !(err instanceof ToolUserError)) return err;
143		const internalValidatorPrefix = /Invalid arguments for manage_[a-z_]+/;
144		if (!internalValidatorPrefix.test(err.message)) return err;
145		const rewritten = err.message
146			.replace(
147				internalValidatorPrefix,
148				`Invalid arguments for client.${sdkNamespace}.${publicMethod}`,
149			)
150			// The valid-args list is scoped to the INTERNAL action (`for action
151			// 'read_feed'`) — drop that fragment once the public method already names
152			// the call, so no internal action name survives in the message.
153			.replace(/ for action '[a-z_]+'/, "")
154			// A shared admin-tool schema lists every field for every action. That list
155			// is both internal (`action`) and wrong for named SDK methods (for example,
156			// conversations.list used to advertise send-only fields). Keep the actual
157			// unknown/missing-field detail, then route the caller to the authoritative
158			// public signature instead of leaking the raw union schema.
159			.replace(
160				/ — valid arguments are: .+$/,
161				` — run search_sdk '${sdkNamespace}.${publicMethod}' for the public signature`,
162			);
163		if (rewritten === err.message) return err;
164		// ClientSdkActionError carries extra fields — but it is raised by THIS module
165		// from a result value, never by the arg validator, so a match here is always
166		// a plain ToolUserError. Preserve the httpStatus.
167		return new ToolUserError(rewritten, err.httpStatus);
168	}
