 59	/**
 60	 * Predicate for the `connections` row itself (its own metadata / operation
 61	 * targets). Returns an `AND (...)` fragment (no leading space) of plain SQL
 62	 * text: the principal is a server-derived user id (never client text) embedded
 63	 * as an escaped literal, so the ONE predicate is usable both in positional
 64	 * `sql.unsafe(query, params)` builders and inside tagged-template queries via
 65	 * `sql.unsafe(fragment)` — no per-caller param-index bookkeeping to drift.
 66	 */
 67	export function compileConnectionRowVisibility(scope: AuthzScope, tableAlias: string): string {
 68	  const arms = [`${tableAlias}.visibility = 'org'`];
 69	  if (scope.principal != null) {
 70	    arms.push(`${tableAlias}.created_by = ${sqlLiteral(scope.principal)}`);
 71	  }
 72	  // Admin-tier: legacy-unowned rows (created_by IS NULL) are org assets with no
 73	  // creator whose credential privacy could be violated — owners/admins may see
 74	  // and use them. Never widens rows that DO have a creator.
 75	  if (scope.principalIsAdmin) {
 76	    arms.push(`${tableAlias}.created_by IS NULL`);
 77	  }
 78	  return `AND (${arms.join(' OR ')})`;
 79	}
