254	  const [direction, setDirection] = useState<'source' | 'target'>('source');
255	
256	  // New relationship type creation
257	  const [newName, setNewName] = useState('');
258	  const [newSlug, setNewSlug] = useState('');
259	  const [newSymmetric, setNewSymmetric] = useState(false);
260	
261	  const [error, setError] = useState<string | null>(null);
262	
263	  const createRelTypeMutation = useCreateRelationshipType();
264	  const addRuleMutation = useAddRelationshipTypeRule();
265	
266	  const reset = () => {
267	    setMode('existing');
268	    setSelectedRelTypeSlug('');
269	    setTargetEntityTypeSlug('');
270	    setDirection('source');
271	    setNewName('');
272	    setNewSlug('');
273	    setNewSymmetric(false);
274	    setError(null);
275	  };
276	
277	  const handleOpenChange = (next: boolean) => {
278	    setOpen(next);
279	    if (!next) reset();
280	  };
281	
282	  const slugify = (name: string) =>
283	    name
284	      .toLowerCase()
285	      .replace(/[^a-z0-9]+/g, '_')
286	      .replace(/^_+|_+$/g, '');
287	
288	  const handleSave = async () => {
289	    setError(null);
290	
291	    try {
292	      let relTypeSlug = selectedRelTypeSlug;
293	
294	      if (mode === 'new') {
295	        if (!newName.trim()) {
296	          setError('Name is required');
297	          return;
298	        }
299	        const slug = newSlug.trim() || slugify(newName);
300	        if (!slug) {
301	          setError('Slug is required');
302	          return;
303	        }
304	        const result = await createRelTypeMutation.mutateAsync({
305	          slug,
306	          name: newName.trim(),
307	          is_symmetric: newSymmetric,
308	        });
309	        relTypeSlug = result.relationship_type.slug;
310	      }
311	
312	      if (!relTypeSlug) {
313	        setError('Select a relationship type');
314	        return;
315	      }
316	      if (!targetEntityTypeSlug) {
317	        setError('Select a target entity type');
318	        return;
319	      }
320	
321	      const sourceSlug = direction === 'source' ? entityTypeSlug : targetEntityTypeSlug;
322	      const targetSlug = direction === 'source' ? targetEntityTypeSlug : entityTypeSlug;
323	
324	      await addRuleMutation.mutateAsync({
325	        slug: relTypeSlug,
326	        source_entity_type_slug: sourceSlug,
327	        target_entity_type_slug: targetSlug,
328	      });
329	
330	      handleOpenChange(false);
331	    } catch (e) {
332	      setError(e instanceof Error ? e.message : 'An error occurred');
333	    }
334	  };
